-- Create "personal_access_tokens" table
CREATE TABLE "core"."personal_access_tokens" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "name" character varying NOT NULL, "token_hash" character varying NOT NULL, "prefix" character varying NOT NULL, "expires_at" timestamptz NOT NULL, "revoked_at" timestamptz NULL, "created_at" timestamptz NOT NULL, "user_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "personal_access_tokens_users_user" FOREIGN KEY ("user_id") REFERENCES "core"."users" ("id") ON UPDATE NO ACTION ON DELETE CASCADE);
-- Create index "personal_access_tokens_token_hash_key" to table: "personal_access_tokens"
CREATE UNIQUE INDEX "personal_access_tokens_token_hash_key" ON "core"."personal_access_tokens" ("token_hash");
-- Create index "personalaccesstoken_user_id" to table: "personal_access_tokens"
CREATE INDEX "personalaccesstoken_user_id" ON "core"."personal_access_tokens" ("user_id");
